<?php
session_start();
require_once __DIR__ . '/../lead-engine/config.php';
if(empty($_SESSION['mp_dashboard_auth'])){header('Location:/dashboard/?next='.rawurlencode($_SERVER['REQUEST_URI']??'/dashboard/scout-workdesk.php'));exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sb($ep){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json'],CURLOPT_TIMEOUT=>25]);$b=curl_exec($ch);$http=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$d=json_decode($b,true);return($http>=200&&$http<300&&is_array($d))?$d:[];}
$leads=sb('leads?select=*&order=created_at.desc&limit=150');
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Scout Leads Desk</title><style>body{margin:0;background:#070b14;color:#edf3ff;font-family:Inter,system-ui,Segoe UI,Arial}.wrap{max-width:1350px;margin:0 auto;padding:24px}.top{display:flex;justify-content:space-between;align-items:center}.btn{background:#101a2b;border:1px solid #263751;color:#dce8ff;text-decoration:none;font-weight:800;border-radius:12px;padding:10px 14px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(310px,1fr));gap:14px;margin-top:22px}.card{background:#0b1220;border:1px solid #263751;border-radius:18px;padding:16px}.hot{border-color:#f3b94e}.meta{color:#8fa4c1;font-size:12px;text-transform:uppercase;letter-spacing:.08em}.card h2{margin:8px 0}.row{display:grid;grid-template-columns:86px 1fr;gap:8px;margin:8px 0}.k{color:#8fa4c1}.v{word-break:break-word}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.action{background:#17263a;border:1px solid #36506d;color:#eaf2ff;text-decoration:none;border-radius:10px;padding:8px 10px;font-weight:800}.primary{background:#2b1b07;border-color:#f3b94e;color:#ffe9ad}.empty{border:1px dashed #34465f;border-radius:18px;padding:28px;color:#9fb0ca;margin-top:20px}</style></head><body><div class="wrap"><div class="top"><div><h1>Scout Leads Desk</h1><p style="color:#9fb0ca">Speed to lead: every known lead with phone/email/address, ready to call.</p></div><div><a class="btn" href="/dashboard/goliath-deliverables.php?agent=Scout">Deliverables</a> <a class="btn" href="/dashboard/goliath-mission-control.php">Mission Control</a></div></div><?php if(!$leads):?><div class="empty">No leads found yet. Test the website valuation form, import an approved list, or run Scout Production.</div><?php endif;?><div class="grid"><?php foreach($leads as $l):$phone=$l['phone']??'';$email=$l['email']??'';$addr=$l['address']??'';$town=$l['town']??'';$score=(int)($l['lead_score']??0);?><div class="card <?=$score>=80?'hot':''?>"><div class="meta"><?=h($l['type']??'lead')?> · <?=h(date('M j g:i A',strtotime($l['created_at']??'now')))?></div><h2><?=h($l['name']?:'Unknown Lead')?></h2><div class="row"><div class="k">Phone</div><div class="v"><?=h($phone?:'—')?></div><div class="k">Email</div><div class="v"><?=h($email?:'—')?></div><div class="k">Address</div><div class="v"><?=h(trim($addr.' '.$town)?:'—')?></div><div class="k">Score</div><div class="v"><?=h($score?:'—')?></div><div class="k">Source</div><div class="v"><?=h($l['source']??'—')?></div><div class="k">Message</div><div class="v"><?=h($l['message']??($l['goal']??'—'))?></div></div><div class="actions"><?php if($phone):?><a class="action primary" href="tel:<?=h(preg_replace('/[^0-9+]/','',$phone))?>">Call</a><a class="action" href="sms:<?=h(preg_replace('/[^0-9+]/','',$phone))?>">Text</a><?php endif;?><?php if($email):?><a class="action" href="mailto:<?=h($email)?>">Email</a><?php endif;?><?php if($addr||$town):?><a class="action" target="_blank" href="https://www.google.com/maps/search/<?=rawurlencode(trim($addr.' '.$town.' CT'))?>">Map</a><?php endif;?></div></div><?php endforeach;?></div></div></body></html>
